// Leemos el comando que nos envía la IA.
const contratoString = $json.json_command;

if (typeof contratoString !== 'string' || contratoString.trim() === '') {
    throw new Error("Error de Inyección: El parámetro 'json_command' está vacío o no es un string válido.");
}

let contratoObjeto;
try {
    let tempString = contratoString;
    let filterValue = null;

    // --- CIRUGÍA DE PRECISIÓN ---
    const filterRegex = /'filter'\s*:\s*'((?:\\'|[^'])*)'/;
    const match = tempString.match(filterRegex);

    if (match) {
        filterValue = match[1]; 
        tempString = tempString.replace(filterRegex, "'filter':'__FILTER_PLACEHOLDER__'");
    }

    let correctedString = tempString.replace(/'/g, '"');

    if (filterValue !== null) {
        correctedString = correctedString.replace('"__FILTER_PLACEHOLDER__"', JSON.stringify(filterValue));
    }

    contratoObjeto = JSON.parse(correctedString);

    // --- VALIDACIONES UNIVERSALES Y ESPECÍFICAS (ESTANDARIZADAS) ---
    if (typeof contratoObjeto.action !== 'string' || contratoObjeto.action.trim() === '') {
        throw new Error("Error de Contrato: La clave 'action' es obligatoria y debe ser un string no vacío.");
    }

    const actionsWithoutCollection = ['list_collections_with_schema'];
    if (!actionsWithoutCollection.includes(contratoObjeto.action)) {
        if (typeof contratoObjeto.collection !== 'string' || contratoObjeto.collection.trim() === '') {
            throw new Error(`Error de Contrato: La clave 'collection' es obligatoria para la acción '${contratoObjeto.action}'.`);
        }
    }

    // Estandarización a 'id' para operaciones únicas
    if (contratoObjeto.action === 'delete_record' || contratoObjeto.action === 'update_record') {
        if (typeof contratoObjeto.id !== 'string' || contratoObjeto.id.trim() === '') {
            throw new Error(`Error de Contrato: La clave 'id' es obligatoria para la acción '${contratoObjeto.action}'.`);
        }
    }

    if (contratoObjeto.action === 'update_record') {
        if (typeof contratoObjeto.data !== 'object' || contratoObjeto.data === null) {
            throw new Error("Error de Contrato: La clave 'data' (un objeto) es obligatoria para 'update_record'.");
        }
    }

    if (contratoObjeto.action === 'batch_delete') {
        if (!Array.isArray(contratoObjeto.record_ids)) {
            throw new Error("Error de Contrato: La clave 'record_ids' (un array) es obligatoria para 'batch_delete'.");
        }
    }

    if (contratoObjeto.action === 'batch_update') {
        if (!Array.isArray(contratoObjeto.records)) {
            throw new Error("Error de Contrato: La clave 'records' (un array) es obligatoria para 'batch_update'.");
        }
    }

} catch (error) {
    // El 'contratoString' ahora está definido y accesible en este scope.
    throw new Error(`Error de Sintaxis en el JSON: ${error.message}. JSON original recibido: '${contratoString}'`);
}

// Devolvemos el objeto JSON limpio y validado.
return [{ json: contratoObjeto }];

const fetch = require('node-fetch');

// --- CONFIGURACIÓN ---
const POCKETBASE_BASE_URL = 'http://127.0.0.1:8090';
const ADMIN_EMAIL = 'elprofesorverdad@gmail.com';
const ADMIN_PASSWORD = 'Copa007copa.';
// -------------------

const contract = $json;
let adminToken = null;

// --- FUNCIONES AUXILIARES ---
async function getAdminToken() {
    if (adminToken) return adminToken;
    const response = await fetch(`${POCKETBASE_BASE_URL}/api/admins/auth-with-password`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ identity: ADMIN_EMAIL, password: ADMIN_PASSWORD }),
    });
    if (!response.ok) throw new Error(`Fallo en la autenticación de admin: ${await response.text()}`);
    const data = await response.json();
    adminToken = data.token;
    return adminToken;
}

async function translateError(response, context = {}) {
    const errorBody = await response.json().catch(() => ({ message: response.statusText }));
    const details = errorBody.data || {};
    if (response.status === 404) return `Error 404: La colección "${context.collection || 'desconocida'}" o un registro no fue encontrado.`;
    if (response.status === 400) {
        if (JSON.stringify(details).toLowerCase().includes("failed to parse filter")) {
             return `Error 400: La sintaxis del filtro es inválida. Revisa los operadores, comillas y nombres de campos.`;
        }
        let errorMessages = Object.entries(details).map(([key, val]) => `Campo '${key}': ${val.message || JSON.stringify(val)}`);
        return `Error 400: Petición incorrecta. Detalles: ${errorMessages.join(', ')}`;
    }
    return `Error ${response.status}: ${response.statusText} - ${JSON.stringify(errorBody)}`;
}

// --- ORQUESTADOR PRINCIPAL ---
async function executePocketBaseOrchestrator() {
    const token = await getAdminToken();
    const headers = { 'Authorization': `Bearer ${token}` };

    switch (contract.action) {

        case 'query_records': {
            let queryString = '';
            const params = contract.params || {};
            if (params.limit) {
                params.perPage = params.limit;
                delete params.limit;
            }
            const queryParts = [];
            for (const key in params) {
                if (params[key] !== undefined && params[key] !== null && params[key] !== '') {
                    queryParts.push(`${encodeURIComponent(key)}=${encodeURIComponent(params[key])}`);
                }
            }
            if (queryParts.length > 0) queryString = '?' + queryParts.join('&');
            const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${contract.collection}/records${queryString}`;
            const response = await fetch(finalUrl, { method: 'GET', headers: headers });
            if (!response.ok) throw new Error(await translateError(response, contract));
            const data = await response.json();
            return data.items;
        }

        case 'list_collections_with_schema': {
            const response = await fetch(`${POCKETBASE_BASE_URL}/api/collections?perPage=500&schema=1`, { headers: headers });
            if (!response.ok) throw new Error(`Fallo al listar colecciones: ${await translateError(response)}`);
            const data = await response.json();
            return data.items.filter(c => !c.system);
        }

        case 'batch_create': {
            headers['Content-Type'] = 'application/json';
            const creationTasks = [];
            const collectionsToCreate = {};
            const dataToCreate = contract.data || contract.records; 
            if (Array.isArray(dataToCreate)) {
                if (!contract.collection) throw new Error("Error de Contrato: 'collection' es obligatorio para batch_create con un array de datos.");
                collectionsToCreate[contract.collection] = dataToCreate;
            } else if (typeof dataToCreate === 'object' && dataToCreate !== null) {
                Object.assign(collectionsToCreate, dataToCreate);
            } else {
                throw new Error("Error de Contrato: El campo 'data' o 'records' para batch_create debe ser un array o un objeto.");
            }
            for (const collectionName in collectionsToCreate) {
                const records = collectionsToCreate[collectionName];
                const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${collectionName}/records`;
                const body = JSON.stringify({ records: records });
                const task = fetch(finalUrl, { method: 'POST', headers, body })
                    .then(async response => {
                        if (!response.ok) throw new Error(`Fallo en 'batch_create' para la colección '${collectionName}': ${await translateError(response, { collection: collectionName })}`);
                        return response.json();
                    });
                creationTasks.push(task);
            }
            const results = await Promise.all(creationTasks);
            return results.reduce((acc, result, index) => {
              const collectionName = Object.keys(collectionsToCreate)[index];
              acc[collectionName] = result;
              return acc;
            }, {});
        }

        case 'delete_record': {
            if (!contract.id) throw new Error("Error de Contrato: 'id' es obligatorio para la acción 'delete_record'.");
            const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${contract.collection}/records/${contract.id}`;
            const response = await fetch(finalUrl, { method: 'DELETE', headers: headers });
            if (!response.ok) throw new Error(`Fallo en 'delete_record': ${await translateError(response, contract)}`);
            return { deleted: true, id: contract.id };
        }

        case 'batch_delete': {
            const idsToDelete = contract.record_ids || [];
            if (idsToDelete.length === 0) {
                return { deleted_count: 0, message: "No record IDs provided to delete." };
            }
            const deletePromises = idsToDelete.map(id => {
                const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${contract.collection}/records/${id}`;
                return fetch(finalUrl, { method: 'DELETE', headers: headers })
                    .then(response => {
                        if (!response.ok) throw new Error(`Failed to delete record with ID: ${id}. Status: ${response.status}`);
                        return id;
                    });
            });
            const deletedIds = await Promise.all(deletePromises);
            return { deleted_count: deletedIds.length, record_ids: deletedIds };
        }

        case 'update_record': {
            headers['Content-Type'] = 'application/json';
            if (!contract.id) throw new Error("Error de Contrato: 'id' es obligatorio para la acción 'update_record'.");
            const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${contract.collection}/records/${contract.id}`;
            const body = JSON.stringify(contract.data);
            const response = await fetch(finalUrl, { method: 'PATCH', headers, body });
            if (!response.ok) throw new Error(`Fallo en 'update_record': ${await translateError(response, contract)}`);
            return await response.json();
        }

        case 'batch_update': {
            headers['Content-Type'] = 'application/json';
            const recordsToUpdate = contract.records || [];
            if (recordsToUpdate.length === 0) {
                return { successful_records: [], failed_records: [], message: "No records provided to update." };
            }
            const updatePromises = recordsToUpdate.map(record => {
                const recordId = record.id;
                if (!recordId) {
                    return Promise.reject({ record_id: 'unknown', error: "Registro sin 'id'." });
                }
                const dataToUpdate = { ...record };
                delete dataToUpdate.id;
                const finalUrl = `${POCKETBASE_BASE_URL}/api/collections/${contract.collection}/records/${recordId}`;
                const body = JSON.stringify(dataToUpdate);
                return fetch(finalUrl, { method: 'PATCH', headers, body })
                    .then(async response => {
                        if (!response.ok) {
                            const errorMsg = await translateError(response, contract);
                            return Promise.reject({ record_id: recordId, error: errorMsg });
                        }
                        return response.json();
                    });
            });
            const results = await Promise.allSettled(updatePromises);
            const successfulUpdates = [];
            const failedUpdates = [];
            results.forEach(result => {
                if (result.status === 'fulfilled') {
                    successfulUpdates.push(result.value);
                } else {
                    failedUpdates.push(result.reason);
                }
            });
            return {
                successful_records: successfulUpdates,
                failed_records: failedUpdates
            };
        }

        default:
            throw new Error(`Acción no soportada o desconocida: '${contract.action}'.`);
    }
}

// --- PUNTO DE ENTRADA CON MANEJO DE ERRORES ROBUSTO ---
try {
    const result = await executePocketBaseOrchestrator();
    return [{ json: { status: 'success', operation: contract.action, result: result } }];
} catch (error) {
    let errorMessage = 'An unknown error occurred inside the orchestrator.';
    if (error instanceof Error) {
        errorMessage = error.message;
    } else if (typeof error === 'string') {
        errorMessage = error;
    } else {
        try {
            errorMessage = JSON.stringify(error);
        } catch (stringifyError) {
            errorMessage = 'Could not stringify the error object.';
        }
    }
    return [{ json: { status: 'error', operation: contract.action, message: errorMessage } }];
}
